package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamPhysicsWaveBank2 {
  private const val T = "තරංග, ධ්වනිය, ප්‍රකාශ විද්‍යාව හා තාපය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "තරංග, ධ්වනිය, ආලෝකය හා තාපයට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("තත්පර 10 කදී කම්පන 2000 ක් සිදු කරන ධ්වනි ප්‍රභවයක සංඛ්‍යාතය කීයද?", "200 Hz", "20,000 Hz", "20 Hz", "0.005 Hz", "සංඛ්‍යාතය f = කම්පන ගණන / කාලය = 2000 / 10 = 200 Hz."),
    q("ආවර්ත කාලය 0.02 s වූ තරංගයක සංඛ්‍යාතය කොපමණද?", "50 Hz", "20 Hz", "500 Hz", "2 Hz", "f = 1 / 0.02 = 50 Hz."),
    q("ශ්‍රී ලංකාවේ ධ්වනි විද්‍යාගාර පරීක්ෂණයකදී සුසර කවලයක් ජල මතුපිටකට තැබූ විට ජල බිඳිති විසි වන්නේ ඇයි?", "ශබ්දය උපදවන ප්‍රභවය කම්පනය වන නිසා", "සුසර කවලයෙන් ජලය රත් වන නිසා", "ජලය හා ලෝහය අතර චුම්භක බලය නිසා", "කම්පනයෙන් ජලය ආම්ලික වන නිසා", "ශබ්දය උපදින්නේ වස්තුවල කම්පනය මගිනි."),
    q("ඝන කන්දක් ඉදිරිපිට සිට අත්පුඩි ගැසූ පුද්ගලයෙකුට තත්පර 1.2 කට පසු ප්‍රතිධ්වනිය ඇසුණි. වාතයේ ධ්වනි වේගය 340 m s⁻¹ නම් කන්දට ඇති දුර කීයද?", "204 m", "408 m", "170 m", "102 m", "දුර = (v × t) / 2 = (340 × 1.2) / 2 = 204 m."),
    q("ගිගුරුම් සහිත වැසි දිනයක විදුලි කෙටීම දැක තත්පර 5 කට පසු ගෙරවිලි හඬ ඇසුණි. අකුණු ගැසූ ස්ථානයට ඇති දුර කොපමණද? (v_sound = 340 m s⁻¹)", "1,700 m (1.7 km)", "68 m", "340 m", "3,400 m", "ආලෝකය ක්ෂණිකව පැමිණේ; ධ්වනි දුර = 340 × 5 = 1,700 m."),
    q("වීදුරු පාත්‍රයක ඇති වතුර නලයක පිඹින විට නලයේ වායු කඳ කෙටි වන තරමට ඇසෙන ශබ්දයේ වෙනස කුමක්ද?", "සංඛ්‍යාතය වැඩි වී තාරතාව ඉහළ යයි", "සංඛ්‍යාතය අඩු වී තාරතාව අඩු වේ", "වාතයේ ධ්වනි වේගය දෙගුණයක් වේ", "ඇසෙන හඬ සම්පූර්ණයෙන්ම නැවතී යයි", "කෙටි වායු කඳක් වේගයෙන් කම්පනය වන බැවින් ඉහළ සංඛ්‍යාතයක් දෙයි."),
    q("ධ්වනි තරංග ගමන් කිරීමේදී මාධ්‍යයේ පීඩනය වැඩිම ස්ථාන හා පීඩනය අඩුම ස්ථාන හඳුන්වන්නේ පිළිවෙළින් කෙසේද?", "සම්පීඩන සහ විරලන කලාප", "තරංග ශීර්ෂ සහ නිම්න කලාප", "ප්‍රධාන නාභි සහ ධ්‍රැව ලක්ෂ්‍ය", "ප්‍රතිධ්වනි සහ විස්තාර කලාප", "අංශු ළං වී ඇති තැන් සම්පීඩන ද ඈත් වී ඇති තැන් විරලන ද වේ."),
    q("බිඳුණු අස්ථි පරීක්ෂා කිරීමට රෝහල්වල භාවිත කරන, මෘදු පටක හරහා ගමන් කර අස්ථි මගින් අවශෝෂණය වන විද්‍යුත් චුම්භක කිරණ වර්ගය කුමක්ද?", "X-කිරණ", "අධෝරක්ත කිරණ", "රේඩියෝ තරංග", "අතිධ්වනි තරංග", "X-කිරණ ඉහළ විනිවිද යෑමේ හැකියාවක් ඇති අයනීකාරක විකිරණයකි."),
    q("පිළිකා සෛල විනාශ කිරීමේ විකිරණ ප්‍රතිකාර හා ශල්‍ය උපකරණ ජීවානුහරණය සඳහා භාවිත කරන අධි ශක්ති තරංග මොනවාද?", "ගැමා කිරණ (Gamma rays)", "ක්ෂුද්‍ර තරංග", "රේඩියෝ තරංග", "අධෝරක්ත කිරණ", "ගැමා කිරණ විද්‍යුත් චුම්භක වර්ණාවලියේ කෙටිම තරංග ආයාමය හා ඉහළම ශක්තිය දරයි."),
    q("පහත දැක්වෙන තරංග අතුරින් විද්‍යුත් චුම්භක වර්ණාවලියට අයත් නොවන්නේ කුමක්ද?", "ධ්වනි තරංග (ශබ්දය)", "දෘශ්‍ය ආලෝකය", "ක්ෂුද්‍ර තරංග", "පාරජම්බුල කිරණ", "ශබ්දය යාන්ත්‍රික තරංගයක් වන අතර අනෙක්වා විද්‍යුත් චුම්භක තරංග වේ."),
    q("සමතල දර්පණයකට ලම්භකව (පතන කෝණය 0° වන සේ) ආලෝක කිරණයක් පතිත වූ විට පරාවර්තන කෝණය කීයද?", "0° (එම මාර්ගයේම ආපසු හැරී යයි)", "90°", "45°", "180°", "පතන කෝණය හා පරාවර්තන කෝණය මනින්නේ අභිලම්බයේ සිටය."),
    q("සමතල දර්පණයක් ඉදිරියේ 1.5 m දුරින් සිටගෙන සිටින සිසුවෙකුට තමා සහ තම ප්‍රතිබිම්බය අතර පෙනෙන මුළු දුර කීයද?", "3.0 m", "1.5 m", "0.75 m", "4.5 m", "වස්තු දුර 1.5 m + ප්‍රතිබිම්බ දුර 1.5 m = 3.0 m."),
    q("පෙරිස්කෝපයක් (Periscope) සෑදීමේදී ඒ තුළ සමතල දර්පණ දෙකක් සවි කළ යුත්තේ තිරසට කීයක කෝණයකින්ද?", "45°", "90°", "60°", "30°", "දර්පණ දෙක එකිනෙකට සමාන්තරව 45° ඇලව තැබූ විට කිරණ 90° බැගින් දෙවරක් හැරී ඇසට පැමිණේ."),
    q("අවතල දර්පණයක නාභි දුර 15 cm වේ නම් එහි වක්‍රතා අරය (R) කොපමණද?", "30 cm", "15 cm", "7.5 cm", "45 cm", "R = 2f = 2 × 15 = 30 cm."),
    q("වස්තුවක් අවතල දර්පණයේ නාභියේ (F) තැබූ විට පරාවර්තනය වන ආලෝක කිරණ කෙබඳුද? (ටෝච් හා වාහන හෙඩ්ලයිට්)", "ප්‍රධාන අක්ෂයට සමාන්තරව දුරට ගමන් කරයි", "පරාවර්තනය වී නාභිය වෙතට එක් වේ", "සෑදෙන ප්‍රතිබිම්බය ඉතා කුඩා වේ", "දර්පණය හරහා පිටුපසට විහිදී යයි", "මේ නිසා ප්‍රබල සමාන්තර ආලෝක කදම්භයක් ලැබේ."),
    q("සූර්ය කුකරයක (Solar cooker) හිරු රැස් එක් තැනකට නාභිගත කර ඉහළ තාපයක් ලබා ගැනීමට භාවිත කරන පරාවර්තකය කුමක්ද?", "පරාවලයික / අවතල දර්පණයක්", "උත්තල දර්පණයක්", "සමතල දර්පණයක්", "අවතල කාචයක්", "සමාන්තර සූර්ය කිරණ නාභියට අභිසාරී කෙරේ."),
    q("ආලෝක කිරණයක් වීදුරුවලින් (වර්තනාංකය 1.5) වාතයට පැමිණෙන විට පතන කෝණය අවධි කෝණයට (~42°) හරියටම සමාන නම් වර්තන කෝණය කීයද?", "90° (මායිම දිගේ ගමන් කරයි)", "0°", "42°", "45°", "පතන කෝණය අවධි කෝණය ඉක්මවූ විගස පූර්ණ අභ්‍යන්තර පරාවර්තනය සිදුවේ."),
    q("උණුසුම් ගිම්හාන දිනවල කාපට් පාරවල් මත ඈතින් වතුර වළවල් ඇති ලෙස 'මිරිඟුව' (Mirage) පෙනෙන්නේ කුමන සංසිද්ධි නිසාද?", "වර්තනය සහ පූර්ණ අභ්‍යන්තර පරාවර්තනය", "සිහින් සිදුරකින් සිදුවන ආලෝක විවර්තනය", "වායු ස්තර හරහා සිදුවන තාප සන්නයනය", "මාර්ග පෘෂ්ඨය මත සිදුවන ශබ්ද පරාවර්තනය", "පොළොව අසල උණුසුම් වාතයේ වර්තනාංකය ඉහළ සිසිල් වාතයට වඩා අඩු වීම මීට හේතුවයි."),
    q("කැමරාවක පටලය/සංවේදකය මත දුරින් ඇති දර්ශනයක තාත්වික, කුඩා කළ, යටිකුරු ප්‍රතිබිම්බයක් සෑදීමට වස්තුව තිබිය යුත්තේ උත්තල කාචයේ කොතැනද?", "2F ට වඩා දුරින්", "F හා කාචය අතර", "හරියටම F මත", "හරියටම 2F මත", "වස්තුව 2F ට වඩා දුරින් ඇති විට ප්‍රතිබිම්බය F හා 2F අතර කුඩාවට සෑදේ."),
    q("සිනමා ප්‍රක්ෂේපණ යන්ත්‍රයක (Projector) කුඩා චිත්‍රපට ස්ලයිඩයකින් තිරය මත විශාල කළ තාත්වික ප්‍රතිබිම්බයක් ගැනීමට එය තැබිය යුත්තේ කොතැනද?", "F සහ 2F අතර", "2F ට දුරින්", "F හා කාචය අතර", "අනන්තයේ", "F හා 2F අතර තැබූ විට ප්‍රතිබිම්බය 2F ට එහායින් විශාලව තාත්විකව සෑදේ."),
    q("සංයුක්ත අන්වීක්ෂයක ඇති ප්‍රධාන ප්‍රකාශ කොටස් දෙක මොනවාද?", "උත්තල අවනෙත සහ උත්තල උපනෙත කාච", "එකම නාභි දුර ඇති අවතල කාච දෙකක්", "පරාවර්තනය සඳහා සමතල දර්පණ දෙකක්", "විශාලනය සඳහා උත්තල දර්පණ දෙකක්", "අවනෙත පළමු විශාලනය ද උපනෙත දෙවන විශාලනය ද සිදු කරයි."),
    q("නිල් පැහැති වීදුරු පෙරහනක් (Blue filter) තුළින් සුදු ආලෝකය යැවූ විට එහා පසින් පිටවන්නේ කුමන වර්ණය පමණද?", "නිල් ආලෝකය පමණි", "රතු ආලෝකය", "කොළ ආලෝකය", "සුදු ආලෝකය", "වර්ණ පෙරහනක් එහිම වර්ණය පමණක් විනිවිද යෑමට ඉඩ දී අනෙක් වර්ණ අවශෝෂණය කර ගනී."),
    q("දහවල් කාලයේදී අහස නිල් පැහැයෙන් පෙනීමටත් ඉර බැස යන විට බටහිර අහස රතු-තැඹිලි පැහැයෙන් පෙනීමටත් හේතුව කුමක්ද?", "වායුගෝලීය අංශු මඟින් නිල් ආලෝකය ප්‍රකිරණය වීම", "වායුගෝලයේ වාතය ස්වභාවයෙන් නිල් පැහැති වීම", "පෘථිවි සාගරයේ නිල් වර්ණය ඉහළට පරාවර්තනය වීම", "වායුගෝලීය ඕසෝන් ස්තරය සවසට රතු පැහැති වීම", "රේලේ ප්‍රකිරණය නිසා ඉර බසින විට දිගු තරංග ආයාම ඇති රතු ආලෝකය අප වෙත ළඟා වේ."),
    q("සාමාන්‍යයෙන් ඝන, ද්‍රව සහ වායු යන අවස්ථා තුන සමාන උෂ්ණත්ව වෙනසකින් රත් කළ විට වැඩියෙන්ම ප්‍රසාරණය වන්නේ කුමක්ද?", "වායු", "ද්‍රව", "ඝන", "සියල්ලම සමානය", "වායු අණු අතර ආකර්ෂණ බල ඉතාම අඩු බැවින් රත් කළ විට පරිමාව විශාල ලෙස වැඩි වේ."),
    q("වායුගෝලීය උෂ්ණත්වය 4°C සිට 0°C දක්වා පහළ බසින විට පොකුණක ජලය සිසිල් වී ගැඹුරු පතුලේ ජලය 4°C හි රැඳී අයිස් මතුපිට පාවීමට හේතුව කුමක්ද?", "4°C ජල ඝනත්වය උපරිම වී අයිස් ඝනත්වය අඩු වීම", "අයිස්වල ඝනත්වය 2000 kg m⁻³ තරම් ඉහළ වීම", "පොකුණ පතුලේ ජල උෂ්ණත්වය 100°C ලෙස පැවතීම", "ජලජ මත්ස්‍යයන් නිරන්තරයෙන් තාපය නිපදවීම", "මතුපිට අයිස් තට්ටුව පරිවාරකයක් ලෙස ක්‍රියා කර පතුල මිදීම වළක්වයි."),
    q("තඹ දණ්ඩක් එක් කෙළවරකින් රත් කළ විට අනෙක් කෙළවරට තාපය ගමන් කරන ක්‍රමය කුමක්ද?", "තාප සන්නයනය (Conduction)", "සංවහනය", "විකිරණය", "වාෂ්පීභවනය", "අංශු ස්ථාන මාරු නොවී කම්පන හා නිදහස් ඉලෙක්ට්‍රෝන මගින් තාපය සම්ප්‍රේෂණය වේ."),
    q("වීදුරු කාමරයක සිවිලිමට ආසන්නව වායුසමීකරණ යන්ත්‍රය (AC) සවි කරන්නේ කුමන තාප සංක්‍රමණ ක්‍රමය ප්‍රයෝජනයට ගැනීමටද?", "සිසිල් වාතය පහළ බසින සංවහන ධාරා", "බිත්ති ඔස්සේ සිදුවන තාප සන්නයනය", "සිවිලිමෙන් පහළට එන තාප විකිරණය", "වායු ස්තර තුළ සිදුවන ආලෝක වර්තනය", "මීට ප්‍රතිවිරුද්ධව කාමර රත් කරන හීටර පොළොවට ආසන්නව සවි කෙරේ."),
    q("සූර්යාලෝකය නොමැති අවකාශයක හෝ ගින්නක් ඉදිරිපිට අත ඇල්ලූ විට පැත්තෙන් අපට උණුසුම දැනෙන්නේ කෙසේද?", "තාප විකිරණය මගිනි", "සංවහනය මගිනි (උණුසුම් වාතය යන්නේ ඉහළටය)", "සන්නයනය මගිනි (වාතය දුර්වල සන්නායකයකි)", "ප්‍රතිධ්වනිය මගිනි", "විකිරණ තාපය සෑම දිශාවකටම සරල රේඛීයව ගමන් කරයි."),
    q("පිත්තල කැබැල්ලක්, තඹ කැබැල්ලක් හා ඇලුමිනියම් කැබැල්ලක් එකම උෂ්ණත්වයට රත් කර ජලයට දැමූ විට ජලයේ උෂ්ණත්වය වැඩියෙන්ම ඉහළ දමන්නේ කවරක්ද? (Al හි c = 900, Cu හි c = 385)", "ඇලුමිනියම් (වැඩිම විශිෂ්ට තාප ධාරිතාව)", "රතු පැහැති තඹ ලෝහ කැබැල්ල මගිනි", "රන්වන් පැහැති පිත්තල කැබැල්ල මගිනි", "ලෝහ තුනම සමාන උෂ්ණත්ව වැඩිවීමක් දෙයි", "සමාන ස්කන්ධ හා උෂ්ණත්ව වෙනසකදී Q ∝ c වේ."),
    q("තාපමිතික ගණනයකදී 40°C ජලය 1 kg ක් සහ 80°C ජලය 1 kg ක් මිශ්‍ර කළ විට තාප හානි නොමැති නම් අවසන් සමතුලිත උෂ්ණත්වය කීයද?", "60°C", "40°C", "80°C", "120°C", "සමාන ස්කන්ධ හා සමාන ද්‍රව නිසා සාමාන්‍යය (40 + 80)/2 = 60°C."),
    q("මිනිසා දහඩිය දැමීමෙන් පසු සුළං හමන විට සිරුර වඩාත් සිසිල් බවක් දැනෙන්නේ ඇයි?", "දහඩිය වේගයෙන් වාෂ්ප වී ගුප්ත තාපය උරා ගැනීම", "හමා එන සුළඟ තුළ කුඩා අයිස් අංශු අඩංගු වීම", "සිරුර මතුපිට ඇති දහඩිය ඝන තට්ටුවක් වීම", "සුළඟ නිසා සිරුරේ තාප ධාරිතාව වැඩි වීම", "වාෂ්පීභවනය සිසිලන ක්‍රියාවලියකි."),
    q("ද්‍රවයක තාපාංකය හා හිමාංකය සැලකීමේදී, වීදුරු බඳුනක නටන ජලයට තවදුරටත් තාපය දෙමින් දැල්ල වැඩි කළහොත් ජලයේ උෂ්ණත්වය කෙසේ වෙනස් වේද?", "100°C හි නියතව පවතින අතර වාෂ්ප වේගය වැඩි වේ", "ජලයේ උෂ්ණත්වය ඉක්මනින් 120°C දක්වා ඉහළ යයි", "ජලයේ උෂ්ණත්වය ක්‍රමයෙන් 90°C දක්වා අඩු වේ", "නටන ජලයේ උෂ්ණත්වය ක්ෂණිකව 150°C බවට පත් වේ", "සාමාන්‍ය පීඩනයේදී විවෘත බඳුනක ජලය 100°C ඉක්මවා නොයයි."),
    q("තාප සන්නයනය අඩුම ද්‍රව්‍ය කුමන කාණ්ඩයට අයත්ද?", "වාතය, ප්ලාස්ටික් හා වීදුරු පුළුන්", "තඹ, රිදී හා පිරිසිදු රන් ලෝහ", "ඇලුමිනියම්, පිත්තල සහ යකඩ", "ද්‍රව අවස්ථාවේ පවතින රසදිය ලෝහය", "ශීත රටවල නිවාස බිත්ති අතර හා ජැකට්වල සිර කළ වාතය තාප පරිවාරකයක් ලෙස යොදා ගනී."),
    q("සරල උත්තල කාචයක ප්‍රධාන අක්ෂයට සමාන්තරව පැමිණෙන ආලෝක කිරණ කාචය හරහා වර්තනය වූ පසු හමුවන ලක්ෂ්‍යය කුමක්ද?", "ප්‍රධාන නාභිය (Principal focus, F)", "වක්‍රතා කේන්ද්‍රය", "ප්‍රකාශ කේන්ද්‍රය", "ධ්‍රැවය", "උත්තල කාචයේ නාභිය තාත්වික වන අතර අවතල කාචයේ නාභිය අතාත්වික වේ."),
    q("වීදුරුවලින් සැදුම්ලත් කැමරාව හා මිනිස් ඇස සංසන්දනයේදී කැමරාවේ 'පටලයට/සංවේදකයට' සමාන මිනිස් ඇසේ කොටස කුමක්ද?", "දෘෂ්ටි විතානය (Retina)", "තාරා මණ්ඩලය", "කණීනිකාව", "ස්වච්ඡ මණ්ඩලය", "ආලෝක සංවේදී යෂ්ටි හා කේතු සෛල දෘෂ්ටි විතානයේ පිහිටයි."),
    q("රෝගියෙකුගේ ඇසේ කාචය වයසට යත්ම අපැහැදිලි (වළාකුළු වැනි) වී ආලෝකය ගමන් කිරීම වැළකෙන රෝග තත්ත්වය කුමක්ද?", "ඇසේ සුද ඇතිවීම (Cataract)", "වර්ණ අන්ධතාව", "අවිදුරදෘෂ්ටිකත්වය", "ග්ලුකෝමාව", "ශල්‍යකර්මයකින් අපැහැදිලි කාචය ඉවත් කර කෘත්‍රිම අන්තර්අක්ෂි කාචයක් (IOL) බද්ධ කෙරේ."),
    q("ඇසේ කාචය මගින් දෘෂ්ටි විතානය මත සාදන ප්‍රතිබිම්බයේ ස්වභාවය කුමක්ද?", "තාත්වික, කුඩා කළ හා යටිකුරු ප්‍රතිබිම්බයකි", "අතාත්වික, කුඩා කළ හා උඩුකුරු ප්‍රතිබිම්බයකි", "අතාත්වික, විශාල කළ හා උඩුකුරු ප්‍රතිබිම්බයකි", "වස්තුවේ සැබෑ ප්‍රමාණයට සමාන ප්‍රතිබිම්බයකි", "මොළය විසින් එම යටිකුරු ප්‍රතිබිම්බය ස්වයංක්‍රීයව නිවැරදි උඩුකුරු රූපයක් ලෙස අර්ථකථනය කරයි."),
    q("කිසියම් ද්‍රව්‍යයක නාභි දුර -0.5 m ලෙස සටහන් කර ඇති උපැස් කාචය කුමන වර්ගයක්ද? එහි ක්ෂමතාව කීයද?", "අවතල කාචය; -2 D", "උත්තල කාචය; +2 D", "අවතල කාචය; -0.5 D", "උත්තල කාචය; +0.5 D", "සෘණ නාභි දුර අවතල කාච පෙන්වයි; P = 1 / (-0.5) = -2 D."),
    q("රසායනාගාරයක උණුසුම් තාපකයකින් කාමරයට තාපය මුදා හැරීමේදී තාපකයට දීප්තිමත් රිදී පැහැයක් ආලේප කළහොත් කුමක් සිදුවේද?", "විකිරණ මඟින් තාපය පිටවීම අඩු වේ", "විකිරණය දෙගුණ වේ", "විදුලිය ඉතිරි වේ", "කාමරය ඉක්මනින් රත් වේ", "දිලිසෙන ලා පෘෂ්ඨ දුර්වල විකිරණ විමෝචක වේ."),
    q("සංඛ්‍යාතය වැඩි වන පිළිවෙළට විද්‍යුත් චුම්භක තරංග පෙළගැස්වූ විට නිවැරදි අනුපිළිවෙළ කුමක්ද?", "රේඩියෝ < අධෝරක්ත < දෘශ්‍ය ආලෝකය < X-කිරණ", "X-කිරණ < දෘශ්‍ය < රේඩියෝ", "දෘශ්‍ය < අධෝරක්ත < රේඩියෝ", "ගැමා < රේඩියෝ < UV", "සංඛ්‍යාතය ඉහළ යන විට ශක්තිය වැඩි වී තරංග ආයාමය කෙටි වේ."),
    q("නොනැසී පවතින කැඩපත් හෝ ජල පෘෂ්ඨයක සිදුවන 'නිත්‍ය පරාවර්තනය' (Regular reflection) හා රළු බිත්තියක සිදුවන 'විසරිත පරාවර්තනය' අතර වෙනස කුමක්ද?", "නිත්‍යයේදී පැහැදිලි රූප සෑදී විසරිතයේදී කිරණ විහිදේ", "විසරිත පරාවර්තනයේදී ආලෝක පරාවර්තන නියම බිඳ වැටේ", "නිත්‍ය පරාවර්තනය සිදුවන්නේ සම්පූර්ණ අඳුරේ පමණි", "මෙම පරාවර්තන ක්‍රම දෙක අතර කිසිදු වෙනසක් නැත", "සෑම කිරණයක්ම තනි තනිව පරාවර්තන නියම පිළිපදී."),
    q("සමතල වීදුරුවක් වෙනුවට සාමාන්‍යයෙන් කෝණික වීදුරු කැබැල්ලක් හෙවත් ප්‍රිස්මයක් දුරදක්නවල (Binoculars) භාවිත කරන්නේ ඇයි?", "පූර්ණ අභ්‍යන්තර පරාවර්තනයෙන් උපරිම ආලෝකය හැරවීමට", "සමතල දර්පණවලට වඩා ප්‍රිස්ම මිලෙන් ඉතා ලාභ නිසා", "සෑදෙන ප්‍රතිබිම්බය වඩාත් බොඳ වී පෙනෙන පරිදි සැකසීමට", "පිටතින් එන සියලුම ආලෝක කිරණ සම්පූර්ණයෙන් උරා ගැනීමට", "45°-90°-45° ප්‍රිස්ම බයිනෝකියුලරවල යොදා ගනී."),
    q("ඝන ද්‍රව්‍යයක් රත් කළ විට එහි දිග වැඩි වීම 'රේඛීය ප්‍රසාරණය' නම් වේ. යකඩ හා පිත්තල දෙකෙන් වැඩියෙන් ප්‍රසාරණය වන්නේ කුමක්ද?", "පිත්තල", "යකඩ", "දෙකම සමානය", "දෙකම සංකෝචනය වේ", "පිත්තලවල රේඛීය ප්‍රසාරණතාව යකඩවලට වඩා 1.5 ගුණයක් පමණ වැඩිය."),
    q("රසදිය තාපමානයක් උණු වතුරේ බහාලූ විගස මුලින්ම රසදිය මට්ටම ඉතා සුළු වශයෙන් පහත වැටී ඉන්පසු ඉහළ නගින්නේ ඇයි?", "පළමුව වීදුරු බල්බය ප්‍රසාරණය වීම නිසා", "තාපය නිසා රසදිය සංකෝචනය වීම නිසා", "රසදිය ඉක්මනින් වාෂ්ප වී යාම නිසා", "බාහිර ජලය තවමත් සීතල වීම නිසා", "ඉන්පසු රසදිය රත් වී වීදුරුවට වඩා බොහෝ වැඩියෙන් ප්‍රසාරණය වී ඉහළ නගී."),
    q("සුළං සංගීත භාණ්ඩයක හෝ බටනලාවක සිදුරු වැසීමෙන් හා ඇරීමෙන් වෙනස් කරන්නේ කුමක්ද?", "කම්පනය වන වායු කඳේ දිග හා සංඛ්‍යාතය", "බටනලාව තුළ වාතයේ ධ්වනි ප්‍රචාරණ වේගය", "වාදනය කරන බටනලාවේ මුළු ස්කන්ධය හා බර", "වාදනය කරන කාමරයේ පවතින වායු උෂ්ණත්වය", "විවිධ සංගීත ස්වර නිපදවන්නේ කම්පන දිග වෙනස් කිරීමෙනි."),
    q("කිසියම් ලක්ෂ්‍යයක ඇති වස්තුවක් පියවි ඇසින් හා දෘශ්‍ය ආලෝකයෙන් නිරීක්ෂණය කිරීමේදී පැහැදිලිව නොපෙනේ නම්, ඉතා දුරින් ඇති ග්‍රහලෝක හා තරු නිරීක්ෂණයට ගන්නා ප්‍රකාශ උපකරණය කුමක්ද?", "තාරකා විද්‍යාත්මක දුරේක්ෂය", "සංයුක්ත ආලෝක අන්වීක්ෂය", "ආරක්ෂක පෙරිස්කෝපය", "ද්‍රව ඝනත්ව හයිඩ්‍රෝමීටරය", "දුරේක්ෂයේ අවනෙත විශාල නාභි දුරක් ඇති විශාල කාචයක් හෝ අවතල දර්පණයක් වේ."),
    q("කිසියම් ඝන ද්‍රව්‍යයක උෂ්ණත්වය 1°C කින් (හෝ 1 K කින්) ඉහළ නැංවීමට අවශ්‍ය තාප ප්‍රමාණය හඳුන්වන්නේ කෙසේද?", "තාප ධාරිතාව (Heat capacity)", "ගුප්ත තාපය", "තාප සන්නායකතාව", "තාප ප්‍රසාරණය", "තාප ධාරිතාවේ ඒකකය J °C⁻¹ හෝ J K⁻¹ වේ."),
    q("සංඛ්‍යාතය 1,000 Hz වන ශබ්ද තරංගයක් ජලය තුළ (1,500 m s⁻¹) සිට වාතයට (340 m s⁻¹) ඇතුළු වූ විට සංඛ්‍යාතයට සිදුවන්නේ කුමක්ද?", "1,000 Hz ලෙසම නොවෙනස්ව පවතී", "අඩු වේ", "වැඩි වේ", "ශුන්‍ය වේ", "තරංගයක් එක් මාධ්‍යයකින් තවත් මාධ්‍යයකට යන විට වේගය හා තරංග ආයාමය වෙනස් වුවද සංඛ්‍යාතය ප්‍රභවය මත රඳා පවතින බැවින් වෙනස් නොවේ."),
    q("තඹ බඳුනක ඇති 1 kg ජලය හා 1 kg තෙල් එකම සමාන තාප ප්‍රමාණයක් ලබා දුන් විට වැඩිපුර උෂ්ණත්වය ඉහළ යන්නේ කුමකද?", "තෙල් (අඩු විශිෂ්ට තාප ධාරිතාව නිසා)", "පිරිසිදු ජලය (වැඩි තාප ධාරිතාව නිසා)", "ජලය හා තෙල් දෙකම සමානව ඉහළ යයි", "ද්‍රව දෙකෙහිම උෂ්ණත්වය ක්‍රමයෙන් අඩු වේ", "Δθ = Q / (mc) නිසා c කුඩා ද්‍රව්‍යයේ උෂ්ණත්වය වැඩියෙන් නගී."),
    q("දෘශ්‍ය ආලෝක වර්ණාවලියේ 'රතු' සහ 'නිල්' යන වර්ණ දෙක අතරින් වැඩිම තරංග ආයාමයක් ඇත්තේ කුමන වර්ණයටද?", "රතු (≈ 700 nm)", "නිල් (≈ 450 nm)", "දම් (≈ 400 nm)", "දෙකම සමානය", "රතු ආලෝකයට වැඩිම තරංග ආයාමය ඇති නිසා අනතුරු සංඥා සඳහා රතු යොදා ගනී."),
    q("තරංග ආයාමය 0.4 m සහ වේගය 320 m s⁻¹ වූ ධ්වනි තරංගයක සංඛ්‍යාතය කීයද?", "800 Hz", "128 Hz", "320.4 Hz", "80 Hz", "f = v / λ = 320 / 0.4 = 800 Hz."),
    q("සංඛ්‍යාතය 250 Hz වූ තරංගයක ආවර්ත කාලය (T) කොපමණද?", "0.004 s", "0.04 s", "250 s", "0.25 s", "T = 1 / f = 1 / 250 = 0.004 s."),
    q("සමතල දර්පණයක් ඉදිරියේ තැබූ 'AMBULANCE' යන වචනය වාහනයේ ඉදිරිපස කණපිටට ලියා ඇත්තේ කුමන දෘශ්‍ය ගුණය නිසාද?", "පාර්ශ්වික අපවර්තනය නිසා", "සුදු ආලෝක වර්ණ විභේදනය නිසා", "මාධ්‍ය තුළ ආලෝක වර්තනය නිසා", "සිදුරු හරහා ආලෝක විවර්තනය නිසා", "ඉදිරි වාහනයේ පැති හෝ පසුපස දර්පණයෙන් බලන විට එය නිවැරදිව කියවීමට හැකි වේ."),
    q("එකිනෙකට 90° කෝණයකින් තැබූ සමතල දර්පණ දෙකක් අතර තැබූ ඉටිපන්දමක පෙනෙන මුළු ප්‍රතිබිම්බ ගණන කීයද?", "3", "2", "4", "1", "n = (360 / θ) - 1 = (360 / 90) - 1 = 3."),
    q("එකිනෙකට සමාන්තරව මුහුණට මුහුණ ලා තැබූ සමතල දර්පණ දෙකක් අතර වස්තුවක් තැබූ විට සෑදෙන ප්‍රතිබිම්බ ගණන කීයද?", "අනන්ත සංඛ්‍යාවකි", "2", "4", "1", "කෝණය θ = 0° වන විට ප්‍රතිබිම්බ ගණන අනන්ත වේ."),
    q("අවතල දර්පණයක ප්‍රධාන අක්ෂයට සමාන්තරව පැමිණෙන ආලෝක කිරණ පරාවර්තනය වී හමුවන ලක්ෂ්‍යය කුමක්ද?", "ප්‍රධාන නාභිය (F)", "වක්‍රතා කේන්ද්‍රය (C)", "ධ්‍රැවය (P)", "අනන්තය", "නාභි දුර f යනු ධ්‍රැවයේ සිට ප්‍රධාන නාභියට ඇති දුරයි."),
    q("උත්තල දර්පණයකින් ඕනෑම පිහිටීමක ඇති වස්තුවක් සඳහා සාදන ප්‍රතිබිම්බයේ ස්වභාවය කුමක්ද?", "අතාත්වික, උඩුකුරු, කුඩා කළ", "තාත්වික, යටිකුරු, විශාල කළ", "තාත්වික, සමාන ප්‍රමාණයේ", "අතාත්වික, විශාල කළ", "මෙම ගුණය නිසා වාහන පැති දර්පණ ලෙස උත්තල දර්පණ භාවිත වේ."),
    q("වීදුරු කුට්ටියක් තුළට ආලෝක කිරණයක් අභිලම්බය ඔස්සේ (පතන කෝණය 0°) ඇතුළු වූ විට කුමක් සිදුවේද?", "දිශාව වෙනස් නොවී කෙළින්ම ගමන් කරයි", "කිරණය 90° කෝණයකින් නැවී ගමන් කරයි", "ආලෝකය මායිමෙන් සම්පූර්ණයෙන් පරාවර්තනය වේ", "සුදු ආලෝකය වර්ණ 7 කට බෙදී විහිදී යයි", "0° පතන කෝණයකදී වර්තන කෝණය ද 0° වේ; නමුත් වේගය අඩු වේ."),
